// Format content as HTML email
const content = $json.message_content || '';

// Convert markdown-like formatting to HTML
let htmlContent = content
  .replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>')  // Bold
  .replace(/\*([^*]+)\*/g, '<em>$1</em>')             // Italic
  .replace(/^# (.+)$/gm, '<h1>$1</h1>')              // H1
  .replace(/^## (.+)$/gm, '<h2>$1</h2>')             // H2
  .replace(/^### (.+)$/gm, '<h3>$1</h3>')            // H3
  .replace(/^- (.+)$/gm, '<li>$1</li>')              // List items
  .replace(/\n\n/g, '</p><p>')                        // Paragraphs
  .replace(/\n/g, '<br>')                            // Line breaks
  .replace(/(<li>.*<\/li>)/gs, '<ul>$1</ul>')        // Wrap lists
  .replace(/(https?:\/\/[^\s]+)/g, '<a href="$1">$1</a>'); // Links

// Wrap in paragraph tags if not already wrapped
if (!htmlContent.includes('<p>') && !htmlContent.includes('<h1>')) {
  htmlContent = '<p>' + htmlContent + '</p>';
}

const emailTemplate = `
<!DOCTYPE html>
<html>
<head>
    <meta charset="utf-8">
    <title>Alpine Peak Roofing</title>
    <style>
        body { font-family: Arial, sans-serif; line-height: 1.6; color: #333; max-width: 600px; margin: 0 auto; padding: 20px; }
        .header { background: linear-gradient(135deg, #2c5aa0, #1e4080); color: white; padding: 20px; text-align: center; margin-bottom: 20px; }
        .content { background: #f8f9fa; padding: 20px; border-radius: 5px; }
        .footer { margin-top: 20px; padding: 15px; background: #e9ecef; text-align: center; font-size: 12px; }
        a { color: #2c5aa0; }
        h1, h2, h3 { color: #2c5aa0; }
        .cta { background: #2c5aa0; color: white; padding: 10px 20px; text-decoration: none; border-radius: 5px; display: inline-block; margin: 10px 0; }
    </style>
</head>
<body>
    <div class="header">
        <h1>🏔️ Alpine Peak Roofing</h1>
        <p>Pinnacle of Protection, Peak of Performance</p>
    </div>
    <div class="content">
        ${htmlContent}

        <div style="margin-top: 20px; padding: 15px; background: #e3f2fd; border-left: 4px solid #2c5aa0;">
            <strong>📞 Emergency Contact:</strong> (970) 446-8995<br>
            <strong>📅 Schedule Consultation:</strong> <a href="https://calendly.com/jimmy-agenticpersonnel/30min" class="cta">Book Now</a>
        </div>
    </div>
    <div class="footer">
        <p>© 2025 Alpine Peak Roofing | Denver, Colorado<br>
        Professional roofing services for residential and commercial properties</p>
    </div>
</body>
</html>
`;

return {
  json: {
    formatted_content: emailTemplate,
    format: 'html',
    subject: $json.subject,
    email_address: $json.email_address,
    session_id: $json.session_id
  }
};

// Format content as plain text for markdown/text format
const content = $json.message_content || '';

// Clean up any HTML and format as plain text
let textContent = content
  .replace(/<[^>]*>/g, '')                           // Remove HTML tags
  .replace(/\*\*([^*]+)\*\*/g, '$1')                 // Remove bold formatting
  .replace(/\*([^*]+)\*/g, '$1')                     // Remove italic formatting
  .replace(/#{1,6}\s+/g, '')                         // Remove headers
  .replace(/\n{3,}/g, '\n\n')                        // Clean excessive newlines
  .trim();

const emailTemplate = `
🏔️ ALPINE PEAK ROOFING
Pinnacle of Protection, Peak of Performance

=====================================

${textContent}

=====================================

📞 EMERGENCY CONTACT: (970) 446-8995
📅 SCHEDULE CONSULTATION: https://calendly.com/jimmy-agenticpersonnel/30min

© 2025 Alpine Peak Roofing | Denver, Colorado
Professional roofing services for residential and commercial properties
`;

return {
  json: {
    formatted_content: emailTemplate,
    format: $json.format_type,
    subject: $json.subject,
    email_address: $json.email_address,
    session_id: $json.session_id
  }
};
